let semibold:Set<String> = ["chevron.right","arrow.up","xmark"]
func hex(_ h:String)->NSColor{var v:UInt64=0;Scanner(string:String(h.dropFirst())).scanHexInt64(&v);return NSColor(srgbRed:CGFloat((v>>16)&255)/255,green:CGFloat((v>>8)&255)/255,blue:CGFloat(v&255)/255,alpha:1)}
struct Mode{let name,bg,text,muted,glyph,card:String}
let modes=[Mode(name:"light",bg:"#fcfcfb",text:"#252921",muted:"#6b7164",glyph:"#8a5a00",card:"#f1f1ee"),Mode(name:"dark",bg:"#1e1e1e",text:"#e4e4e1",muted:"#a0a09a",glyph:"#f2bb4f",card:"#2a2a29")]
let W:CGFloat=1160, cols=5, cellW:CGFloat=216, cellH:CGFloat=118, pad:CGFloat=40, scale:CGFloat=3
var H:CGFloat=pad+60
for (_,_,its) in sections { H += 44 + CGFloat((its.count+cols-1)/cols)*(cellH+12) + 24 }
H += pad
let outDir = CommandLine.arguments.count>1 ? CommandLine.arguments[1] : NSTemporaryDirectory()
for m in modes {
  let rep=NSBitmapImageRep(bitmapDataPlanes:nil,pixelsWide:Int(W*scale),pixelsHigh:Int(H*scale),bitsPerSample:8,samplesPerPixel:4,hasAlpha:true,isPlanar:false,colorSpaceName:.deviceRGB,bytesPerRow:0,bitsPerPixel:0)!
  rep.size=NSSize(width:W,height:H)
  let base=NSGraphicsContext(bitmapImageRep:rep)!
  let cg=base.cgContext
  cg.translateBy(x:0,y:H); cg.scaleBy(x:1,y:-1)
  let ctx=NSGraphicsContext(cgContext:cg,flipped:true)
  NSGraphicsContext.saveGraphicsState(); NSGraphicsContext.current=ctx
  hex(m.bg).setFill(); NSRect(x:0,y:0,width:W,height:H).fill()
  func text(_ t:String,_ x:CGFloat,_ y:CGFloat,_ size:CGFloat,_ c:String,_ w:NSFont.Weight = .regular,center:Bool=false,width:CGFloat=0){
    let a:[NSAttributedString.Key:Any]=[.font:NSFont.systemFont(ofSize:size,weight:w),.foregroundColor:hex(c)]
    let str=NSAttributedString(string:t,attributes:a); var px=x
    if center { px = x + (width - str.size().width)/2 }
    str.draw(at:NSPoint(x:px,y:y))
  }
  text("图标新旧对照：左边是现在的（Tabler 线条），右边是新的（苹果 SF Symbols）· \(m.name == "light" ? "浅色" : "深色")",pad,pad,22,m.text,.semibold)
  var y=pad+60
  for (title,kind,its) in sections {
    text(title,pad,y,17,m.text,.semibold); y+=44
    for (i,it) in its.enumerated() {
      let cx=pad+CGFloat(i%cols)*(cellW+12), cy=y+CGFloat(i/cols)*(cellH+12)
      let r=NSRect(x:cx,y:cy,width:cellW,height:cellH)
      hex(m.card).setFill(); NSBezierPath(roundedRect:r,xRadius:14,yRadius:14).fill()
      let box:CGFloat = kind=="her" ? 40 : 32
      let oldRect=NSRect(x:cx+38,y:cy+16,width:box,height:box)
      if let b=oldPNG["\(m.name)__\(kind)__\(it.1)"], let d=Data(base64Encoded:b), let img=NSImage(data:d) {
        img.draw(in:oldRect,from:.zero,operation:.sourceOver,fraction:1,respectFlipped:true,hints:nil)
      }
      text("→",cx+cellW/2-7,cy+22,16,m.muted)
      let color = kind=="her" ? m.glyph : m.text
      let pt:CGFloat = kind=="her" ? 24 : 25
      let wt:NSFont.Weight = semibold.contains(it.2) ? .semibold : .regular
      if let base=NSImage(systemSymbolName:it.2,accessibilityDescription:nil),
         let img=base.withSymbolConfiguration(NSImage.SymbolConfiguration(pointSize:pt,weight:wt).applying(NSImage.SymbolConfiguration(paletteColors:[hex(color)]))) {
        let s=img.size; let nx=cx+cellW-38-box+(box-s.width)/2, ny=cy+16+(box-s.height)/2
        img.draw(in:NSRect(x:nx,y:ny,width:s.width,height:s.height),from:.zero,operation:.sourceOver,fraction:1,respectFlipped:true,hints:nil)
      } else { text("缺",cx+cellW-38-box,cy+20,18,"#d0021b",.bold) }
      text(it.0,cx,cy+box+26,14,m.text,.medium,center:true,width:cellW)
      text("\(it.1)  →  \(it.2)",cx,cy+box+48,10.5,m.muted,center:true,width:cellW)
    }
    y += CGFloat((its.count+cols-1)/cols)*(cellH+12)+24
  }
  NSGraphicsContext.restoreGraphicsState()
  let path=(outDir as NSString).appendingPathComponent("himawari-icons-\(m.name).png")
  try! rep.representation(using:.png,properties:[:])!.write(to:URL(fileURLWithPath:path))
  print(path)
}
